// Art direction + animation metadata for every shot (read by scripts/images/restyle.py).
//
// Every shot is first drawn in code: a LAYOUT GUIDE built on the location reference itself
// (src/layout/Plate.tsx) with simple mannequins for who stands where. The final frame is
// generated by the image model (gpt-image-2) from: the layout + the character sheets of
// everyone in the shot + the location reference + the style reference.
//
// How a shot MOVES (no video model needed):
//   - camera: push / drift / handheld on every frame (`move`)
//   - `variants` + `seq`: limited animation - extra DRAWINGS generated as edits of the base
//     frame ("change only X"), merged back onto it so the background never boils, and played
//     in sequence (a hand rising, fingers curling, a head turning) like TV animation on 3s/4s
//   - `blink`: an eyes-closed drawing merged in the eye area, blinked at natural intervals
//   - `doors`: a doors-open drawing; each door is cut from the closed frame and swung open
//     in 3D, one after another
//   - `peephole`: the frame is seen through a door viewer (fisheye lens, round vignette)
//   - `fx`: flicker / shake / tremble / glitch / pulse / whiteout
//   - `talk`: mouth-open drawing swapped in time with the voice (lip sync)
//   - `clip`: a MiniMax image-to-video clip made from the approved frame (when available)
export type CharRef = 'sarah' | 'harris' | 'mother' | 'residents' | 'landlord' | 'creature';
export type LocRef = 'hallway' | 'hallway_cross' | 'flat' | 'bedroom' | 'stairwell' | 'exterior' | 'lobby' | 'office';
export type ShotFx = 'flicker' | 'shake' | 'tremble' | 'glitch' | 'pulse' | 'whiteout';

export interface Variant {
	/** short name: file suffix _v<name> */
	name: string;
	/** what changes in this drawing (everything else stays identical) */
	prompt: string;
}

export interface Art {
	kind: 'still' | 'action' | 'talk' | 'reuse';
	/** What the finished frame shows (prompt text; the layout fixes composition and poses). */
	prompt?: string;
	/** Characters visible in the frame - their sheets go with the request. */
	chars?: CharRef[];
	/** Location reference(s) that go with the request. */
	loc?: LocRef | LocRef[];
	/** Colour mood / lighting for this frame. */
	mood?: string;
	/** action: number of keyframes (default 3) */
	keys?: 2 | 3;
	/** action: where each keyframe takes over, as fractions of the shot (default equal parts) */
	cuts?: number[];
	/** reuse: the shot id whose generated frame(s) this shot shows */
	reuse?: string;
	/** reuse: which keyframe of that shot (default: the middle/only one) */
	key?: number;
	/** camera move on the generated frame: zoom from..to and centre (0..1) */
	move?: {z0?: number; z1?: number; x0?: number; y0?: number; x1?: number; y1?: number};
	fx?: ShotFx;
	/** talk: lines spoken on screen in this shot (mouth variant swaps on these) */
	talk?: string[];
	/** very dark frame - tell the model to keep it dark */
	dark?: boolean;
	/** the frame contains NO people (a strong rule at the top of the prompt) */
	noPeople?: boolean;
	/** action: each later keyframe is generated as an edit of the previous one (same camera) */
	chainKeys?: boolean;
	/** image quality: 'high' for faces / close-ups, 'medium' for wides, dark frames, inserts */
	quality?: 'high' | 'medium';
	/** extra drawings for limited animation (edits of the base frame, merged onto it) */
	variants?: Variant[];
	/** which drawing shows when: [drawing ('base' or a variant name), from (fraction of the shot)] */
	seq?: Array<[string, number]>;
	/** blink: generate an eyes-closed drawing and blink every few seconds */
	blink?: boolean;
	/** doors: a doors-open drawing; doors swing open one after another from `start` (fraction) */
	doors?: {prompt: string; start?: number; stagger?: number; swing?: number};
	/** the frame is seen through the peephole (fisheye + round vignette) */
	peephole?: boolean;
	/** reuse: show this drawing of the source shot ('open' = its doors-open drawing, or a variant name) */
	show?: string;
}
